package taskpkg

import (
	"errors"
	"fmt"
)

// ErrNotFound is returned when a lookup fails.
var ErrNotFound = errors.New("not found")

// Wrap returns a new error that wraps err with a context message. If err is
// nil, returns nil.
func Wrap(err error, msg string) error {
	if err == nil {
		return nil
	}
	return fmt.Errorf("%s: %w", msg, err)
}

// IsNotFound reports whether err (or any error in its chain) is ErrNotFound.
func IsNotFound(err error) bool {
	return errors.Is(err, ErrNotFound)
}

// FirstError returns the first non-nil error in errs, or nil if none.
func FirstError(errs ...error) error {
	for _, e := range errs {
		if e != nil {
			return e
		}
	}
	return nil
}

package taskpkg

import (
	"errors"
	"testing"
)

func TestWrap(t *testing.T) {
	if Wrap(nil, "ctx") != nil {
		t.Error("nil should wrap to nil")
	}
	inner := errors.New("boom")
	wrapped := Wrap(inner, "ctx")
	if !errors.Is(wrapped, inner) {
		t.Error("wrapped error must unwrap to inner")
	}
}

func TestIsNotFound(t *testing.T) {
	if !IsNotFound(ErrNotFound) {
		t.Error("ErrNotFound should be IsNotFound")
	}
	if !IsNotFound(Wrap(ErrNotFound, "ctx")) {
		t.Error("wrapped ErrNotFound should be IsNotFound")
	}
	if IsNotFound(errors.New("other")) {
		t.Error("other error should not be IsNotFound")
	}
}

func TestFirstError(t *testing.T) {
	if FirstError(nil, nil) != nil {
		t.Error("all nil should return nil")
	}
	e := errors.New("x")
	if FirstError(nil, e, errors.New("y")) != e {
		t.Error("should return first non-nil")
	}
}

